<script setup lang="ts">
const {data:me}=await useFetch('/api/auth/me'); if(!me.value?.authenticated) await navigateTo('/login'); const {data:requests,refresh}=await useFetch('/api/requests'); await refresh()
function statusClass(s:string){return s==='approved'?'text-emerald-400':s==='rejected'?'text-red-400':'text-amber-300'}
</script>
<template><div class="space-y-6"><div class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-xs font-black uppercase tracking-[.22em] text-indigo-400">Account</p><h1 class="mt-2 text-3xl font-black">My Requests</h1><p class="mt-1 muted">Requests submitted from {{me?.email}}</p></div><NuxtLink to="/request" class="btn-primary">New request</NuxtLink></div><div v-if="!requests?.length" class="card p-12 text-center"><div class="text-5xl">📨</div><h2 class="mt-4 text-xl font-black">No requests yet</h2><p class="mt-2 muted">Submit your first event request.</p></div><div v-else class="grid gap-4"> <div v-for="r in requests" :key="r.id" class="card flex flex-wrap items-center justify-between gap-4 p-5"><div><h2 class="font-black">{{r.event_name}}</h2><p class="mt-1 text-sm muted">{{r.channel||'Channel not specified'}} · {{r.request_type.toUpperCase()}}</p><p class="mt-1 text-xs muted">{{r.event_date}}</p></div><span class="rounded-full bg-slate-900 px-3 py-1 text-xs font-black capitalize" :class="statusClass(r.status)">{{r.status}}</span></div></div></div></template>
